import type { NormalizedConversation } from '../../domain/models';

/** Entirely invented test conversations; never copied from an account or an export. */
export const qualityCorpus = (threads: readonly (readonly string[])[]): NormalizedConversation[] =>
  threads.map((texts, index) => ({
    id: `quality-thread-${index}`,
    title: `Synthetic conversation ${index}`,
    provider: 'demo',
    createdAt: 1770000000000 + index * 86400000,
    updatedAt: 1770000000000 + index * 86400000,
    messages: texts.map((text, order) => ({
      id: `quality-message-${index}-${order}`,
      conversationId: `quality-thread-${index}`,
      provider: 'demo',
      role: order % 2 === 0 ? 'user' : 'assistant',
      createdAt: 1770000000000 + index * 86400000 + order * 60000,
      order,
      originalText: text,
      analysisText: text,
    })),
  }));

const conversationalOpening = [
  'あ、なるほど。そういうことなんですね。うーん、どうしたらいいのかな。',
  'はい、そうですね。ご質問ありがとうございます。順番に説明します。',
  'じゃあもう少し詳しく教えてほしいです。なんとなくわかってきた気がする。',
  'もちろんです。したがって、まずは条件によって分けるとわかりやすいです。',
] as const;

const conversationalClosing = [
  'いま考えてるところなんだけど、それでいいのかな。具体的にお願いします。',
  '以上を踏まえると、必要に応じて確認することが大切です。参考になれば幸いです。',
  'ありがとうございます。はい、OKです。続けてください！',
  'ご不明な点があれば、お気軽にお知らせください。',
] as const;

