export const expectedSubjectFamilies = [
  ['乳酸発酵'], ['重力波干渉計'], ['分散トレーシング'], ['源泉徴収'], ['藻場再生'],
  ['活版印刷'], ['土壌微生物'], ['勾配降下法'], ['点字楽譜'], ['金継ぎ'],
] as const;

export const naturalMixedTopicCorpus = (): NormalizedConversation[] => qualityCorpus(
  subjectThreads.flatMap((texts) => Array.from({ length: 3 }, (_, repetition) =>
    texts.map((text, order) => [
      conversationalOpening[(order + repetition) % conversationalOpening.length],
      text,
      conversationalClosing[(order + repetition) % conversationalClosing.length],
    ].join('\n\n')))),
);

